/**  The index scan of one session, on the channel its open passed. */
export type LargeFileEvent = { status: "scanning"; sessionId: string; bytesScanned: number; fileBytes: number } | { status: "ready"; sessionId: string; fileBytes: number; lineCount: number } | { status: "error"; sessionId: string; message: string } | { status: "closed"; sessionId: string };

/**  One match: which line, and which occurrence on that line. */
export type LargeFileHit = {
	line: number,
	ordinal: number,
};

/**  `NoteLargeFileInfo`. */
export type LargeFileInfo = {
	reason: LargeFileReasonView,
	fileBytes: number,
	/**  `None` when the file was classified on its size alone and never read. */
	largestBlockBytes: number | null,
};

/**  One page of lines. `lines.len()` says where it ended; `count` was a ceiling. */
export type LargeFileLines = {
	startLine: number,
	lines: string[],
	/**  Absolute line numbers cut at the per-line byte cap. */
	truncated: number[],
	lineCount: number,
};

/**
 *  The answer to opening a large file. `too-large` carries the ceiling as well as the size, so
 *  the renderer never restates a limit this side owns.
 */
export type LargeFileOpenResult = { status: "indexing"; sessionId: string; fileBytes: number } | { status: "ready"; sessionId: string; fileBytes: number; lineCount: number } | { status: "too-large"; fileBytes: number; maxBytes: number } | { status: "missing" };

export type LargeFileReadLinesInput = {
	sessionId: string,
	startLine: number,
	count: number,
};

/**  `NoteLargeFileReason`. */
export type LargeFileReasonView = "file-bytes" | "block-bytes";

export type LargeFileSearchInput = {
	sessionId: string,
	query: string,
};

/**  A count still growing, on the channel the search passed. Never a final answer. */
export type LargeFileSearchProgress = {
	sessionId: string,
	query: string,
	bytesSearched: number,
	fileBytes: number,
	/**  Matches found so far. */
	total: number,
};

/**
 *  The end of one search. `hits` is capped for navigation while `total` counts every match.
 *  `cancelled` is a query a newer one (or a close) superseded.
 */
export type LargeFileSearchResult = { status: "complete"; query: string; hits: LargeFileHit[]; total: number; limited: boolean } | { status: "cancelled"; query: string };

