/**  What a URL download came to: `DownloadAttachmentFromUrlResult` without its `ok` flag. */
export type UrlDownload = { status: "saved"; ref: string } | { status: "failed"; reason: RemoteFailure };

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

/**
 *  Entries of the vault activity log were added or removed, or the vault closed
 *  (`vault-activity:changed`). No payload; the renderer refetches. Throttled by the log.
 */
export type VaultActivityChangedEvent = null;

/**  An entry as the renderer lists it: the fields of the v1 schema, nothing else. */
export type VaultActivityEntry = {
	/**  Always 1. */
	v: number,
	id: string,
	/**  ISO timestamp. */
	at: string,
	kind: VaultActivityKind,
	source: VaultActivitySource,
	/**  Vault-relative path, when the entry is about one file. */
	path?: string,
	oldPath?: string,
	/**  A coded reason; a code from a newer build still parses. */
	reason?: string,
	message?: string,
	importer?: string,
	/**  Numbers as JSON reads them; integers in every writer. */
	counts?: { [key in string]: number },
	items?: string[],
};

/**  `problems` lists skipped and failed entries, and summaries that count either. */
export type VaultActivityFilter = "all" | "problems";

/**  `VAULT_ACTIVITY_KINDS`. */
export type VaultActivityKind = "added" | "removed" | "renamed" | "skipped" | "failed" | "scan" | "import";

export type VaultActivityList = {
	/**  Newest first. */
	entries: VaultActivityEntry[],
	retentionDays: number,
	/**  `false` when no vault is open. */
	available: boolean,
};

/**  `VAULT_ACTIVITY_SOURCES`. */
export type VaultActivitySource = "watcher" | "scan" | "import" | "drop" | "sync";

/**  One stored attachment anywhere in the vault: `VaultAttachmentEntry` of `@memry/rpc/notes`. */
export type VaultAttachmentEntry = {
	ownerNoteId: string,
	/**  `None` when the owning note is gone from the vault; its bytes are still here. */
	ownerNoteTitle: string | null,
	/**  The stored name, `k3f9x2-report.pdf`. */
	filename: string,
	/**  The stored name without its prefix. */
	displayName: string,
	size: number,
	mimeType: string,
	type: AttachmentKind,
	/**  The file's modification time, ISO-8601 in UTC with milliseconds. */
	modifiedAt: string,
};

/**  The vault settings, in the `VaultConfig` shape of `packages/contracts/src/vault-api.ts`. */
export type VaultConfig = {
	excludePatterns: string[],
	defaultNoteFolder: string,
	journalFolder: string,
	journalDateFormat: string,
	attachmentsFolder: string,
	journalShowInSidebar: boolean,
};

/**
 *  The open vault's settings changed (`vault:config-changed`), with the settings after it: an
 *  in-app write, from any window, as Electron's `updateConfig` broadcasts it.
 */
export type VaultConfigChangedEvent = VaultConfig;

/**
 *  The fields a write changes (`UpdateVaultConfigSchema`). `None` leaves the stored value,
 *  whatever it is.
 */
export type VaultConfigPatch = {
	excludePatterns?: string[] | null,
	defaultNoteFolder?: string | null,
	journalFolder?: string | null,
	journalDateFormat?: string | null,
	attachmentsFolder?: string | null,
	journalShowInSidebar?: boolean | null,
};

/**  A vault operation failed (`vault:error`). */
export type VaultErrorEvent = {
	message: string,
};

/**
 *  A reindex, or an open's first index pass, measured `index_built` of `index_total` notes
 *  (`vault:index-progress`). At most one per 250 ms and never backwards within a pass. A pass
 *  that read every file ends with `index_built == index_total` (`0` of `0` for an open with
 *  nothing to measure); one a close or a failed write stops ends without it.
 */
export type VaultIndexProgressEvent = {
	indexBuilt: number,
	indexTotal: number,
};

/**
 *  `index.db` was rebuilt empty (`vault:index-recovered`). `reason` is `missing` for a first
 *  open (nothing was repaired) and `corrupt` otherwise; `detail` is the core's text.
 */
export type VaultIndexRecoveredEvent = {
	reason: string,
	detail: string,
};

/**  The `VaultInfo` of `packages/contracts/src/vault-api.ts`. */
export type VaultInfo = {
	path: string,
	name: string,
	noteCount: number,
	taskCount: number,
	lastOpened: string,
	isDefault: boolean,
	vaultUuid?: string | null,
	isMissing?: boolean | null,
	accentColor?: string | null,
	icon?: string | null,
};

/**  The registry list or a vault's icon changed (`vault:list-changed`). */
export type VaultListChangedEvent = null;

/**  What a lock covers (`VaultLockTargetKind`). */
export type VaultLockKind = "note" | "folder";

/**  `VaultLockSetInput`: a note by id or a folder by vault-relative path. */
export type VaultLockSetInput = {
	kind: VaultLockKind,
	target: string,
	locked: boolean,
};

/**  `VaultLockState`: every locked note id and folder path. */
export type VaultLockStateView = {
	notes: string[],
	folders: string[],
};

/**
 *  A lock was set or lifted on this device, or a vault opened (`vault-locks:changed`): every
 *  locked note id and folder path now.
 */
export type VaultLocksChangedEvent = {
	notes: string[],
	folders: string[],
};

/**
 *  A locked note's file changed or was removed outside the app, and its locked text was written
 *  back; the outside text is a version of the note (`vault-locks:external-edit-restored`).
 */
export type VaultLocksExternalEditRestoredEvent = {
	noteId: string,
	path: string,
	title: string,
};

/**
 *  A state of the open vault the user can act on:
 *  - `configUnreadable`: `.memry/config.json` is there and cannot be read, so the journal days
 *    are unknown: no file becomes a note or a day, and no move reaches its record, until it
 *    reads (`notes::identity`). `path` is the file's, for the user to fix it.
 *  - `watchLimit`: the Linux inotify watch limit left part of the vault unwatched
 *    (`WatchFailed { limit: true }`): changes made outside the app there arrive with the
 *    watcher's rescans, not at once, until the user raises `fs.inotify.max_user_watches` and
 *    restarts.
 *  - `undecidedFiles`: files that have the name of a note or a journal day whose text is not
 *    the file's, or is not on this device yet (`Deferral::Undecided`): they stay files, not
 *    notes, and the next open asks again. `paths` are absolute, for the user to find them.
 *  - `keptRemovals`: files deleted outside the app whose notes were kept, because the note has
 *    text the file never had (`Removed::Undecided`), rather than deleting that text on every
 *    device. Listed until a file is at the note's path again; every open lists them again
 *    while their rows have no file.
 *  - `journalDaysHeld`: journal days a move outside the app carried wait in `folders` (absolute)
 *    for the journal setting to follow them (`journal::folder_follow::Follow::HeldWaits`): no
 *    day is made, no journal setting change moves days, and those folders neither move nor go,
 *    until the days are in one folder they can live in, or back.
 *  - `journalChangeWaits`: a journal setting change from the folder `from` to `to` (as the
 *    setting spells them) a crash cut short could not put its days back
 *    (`vault::journal_rename::finish_journal_change`); `holds` names what keeps them. Both
 *    folders neither move nor go until the next open finishes it.
 *  - `movesWait`: notes whose app move a crash cut short and the open could not finish
 *    (`vault::app_move::finish_interrupted`): they do not move or rename until it settles, which
 *    every open tries again. `path` is the note's file, absolute.
 *  - `journalDaysRenamed`: held journal days (`notes::owed_moves::held`) whose files were renamed
 *    outside the app to a name that no longer names their day, so no follow makes them days
 *    again. Electron would have crossed each into a note; here they stay days until the user
 *    renames them back or turns them into notes (`journal::cross`). `path` is the file's,
 *    absolute.
 *  - `more` says a list notice had more items than [`LISTED`].
 */
export type VaultNotice = { kind: "configUnreadable"; path: string } | { kind: "watchLimit" } | { kind: "undecidedFiles"; paths: string[]; more: boolean } | { kind: "keptRemovals"; notes: KeptRemoval[]; more: boolean } | { kind: "journalDaysHeld"; folders: string[] } | { kind: "journalChangeWaits"; from: string; to: string; holds: ChangeHold } | { kind: "movesWait"; notes: WaitingMove[]; more: boolean } | { kind: "journalDaysRenamed"; days: RenamedDay[]; more: boolean };

/**  The open vault's notices, as a window reads them. */
export type VaultNoticeList = {
	/**
	 *  Changes with every open, so a window forgets the notices the user closed in the vault
	 *  before.
	 */
	open: number,
	notices: VaultNotice[],
};

/**
 *  The open vault's notices changed, or a vault opened or closed. No payload; the renderer
 *  reads `vault_notices_list`.
 */
export type VaultNoticesChangedEvent = null;

export type VaultStatus = {
	isOpen: boolean,
	path: string | null,
	isIndexing: boolean,
	/**  0 to 100. */
	indexProgress: number,
	indexBuilt?: number | null,
	indexTotal?: number | null,
	error: string | null,
	/**  What the open's sweep of interrupted folder moves did, while that vault is open. */
	movesRecovered?: MovesRecovered | null,
	/**
	 *  Higher is newer. The window receives statuses as events and as `vault_get_status`
	 *  answers, which travel apart, so it keeps the one with the higher revision. The shell sets
	 *  it; [`From<SessionStatus>`] leaves it at 0.
	 */
	revision: number,
};

/**
 *  The open vault changed (`vault:status-changed`). The renderer reads the status once after
 *  it subscribes, because events before that are not replayed.
 */
export type VaultStatusChangedEvent = VaultStatus;

/**
 *  `SnapshotDetail`: the version and what a restore puts in the note, which the panel previews:
 *  the version's body ([`restore_body`]). Electron sent the whole file, whose frontmatter its
 *  restore wrote too; this restore keeps the note's.
 */
export type VersionDetailView = {
	id: string,
	noteId: string,
	title: string,
	wordCount: number,
	reason: string,
	createdAt: string,
	fileContent: string,
};

/**
 *  `SnapshotListItem`. `reason` is the stored column, which the renderer reads as
 *  `SnapshotReason`.
 */
export type VersionView = {
	id: string,
	noteId: string,
	title: string,
	wordCount: number,
	reason: string,
	createdAt: string,
};

/**  A note whose interrupted app move waits; `path` is its file's, absolute. */
export type WaitingMove = {
	noteId: string,
	path: string,
};

/**  `WikiLinkPreview`, with the body in place of `bodyText`. */
export type WikiLinkPreviewView = {
	id: string,
	title: string,
	emoji: string | null,
	snippet: string | null,
	tags: PreviewTagView[],
	/**  ISO 8601. */
	createdAt: string,
	/**  The other name the link was written with, `None` when it named the title or path. */
	matchedName: string | null,
	path: string,
	/**  The raw frontmatter `cover`. */
	cover: string | null,
	/**  The note's `description` property when it is text that is not blank. */
	description: string | null,
	/**
	 *  The body after the frontmatter, for the card's opening; `None` when the card shows the
	 *  description instead, or the note is too large for its text to be read.
	 */
	body: string | null,
};

/**
 *  The pointer is over a native caption button (`minimize`, `maximize`, `close`) or left them.
 *  Windows only: the page receives no mouse events for those hit-test regions.
 */
export type WindowCaptionHoverChangedEvent = {
	button: string | null,
};

/**  A native caption button is held down, or released. */
export type WindowCaptionPressedChangedEvent = {
	button: string | null,
};

/**
 *  The main window's maximized or fullscreen state changed (emitted on resize). The renderer
 *  sets `data-fullscreen` on `<html>` and the caption button glyph from it.
 */
export type WindowChromeStateChangedEvent = {
	fullscreen: boolean,
	maximized: boolean,
};

/**
 *  Why a run of failed write-backs began: `write` when a read or a write failed (the next edit
 *  tries again), `frontmatter` when the file's frontmatter does not parse (the file is left
 *  alone until it is fixed).
 */
export type WriteBackFailureReason = "write" | "frontmatter";

/**  `WritingAssistInput` of `@memry/contracts/writing-tools-api`. */
export type WritingAssistInput = { kind: "alternatives"; text: string; context: string };

/**  `WritingAssistResult`. */
export type WritingAssistResult = { kind: "alternatives"; alternatives: string[] };

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
